window.initDecor=function(root){
  root=root||document;
  Object.keys(P).forEach(function(cls){
    root.querySelectorAll('.'+cls).forEach(function(box){
      if(box.querySelector('[data-decor]'))return;
      box.insertAdjacentHTML('afterbegin','<svg data-decor class="absolute" width="0" height="0" aria-hidden="true" focusable="false"><defs>'+P[cls]+'</defs></svg>');
    });
  });
};
